package com.eurobuddha.entropy;

import com.eurobuddha.minimacore.i18n.Language;
import static com.eurobuddha.minimacore.i18n.R.string.*;

/** Explicit Entropy self-test and validation failures only. Never use for user content, names, addresses or filenames.
 * Reuses Parlons SystemMessages' fixed lookup, literal captures and bounded diagnostic recursion.
 * Generated by adapt-pandamonium-entropy-languages.py from localization/entropy-errors.json. */
public final class EntropyMessages {
    private EntropyMessages() {}
    public static CharSequence error(Throwable error) {
        if (error == null) return Language.msg(l10n_wallet_operation_failed);
        return message(error.getMessage() == null ? error.toString() : error.getMessage());
    }
    public static CharSequence message(String value) { return message(value,0); }
    private static CharSequence message(String value,int depth) {
        if (value == null) return "";
        if (depth >= 8) return value;
        switch(value) {
            case "not run": return Language.msg(l10n_entropy_error_not_run);
            case "BIP39 wordlist must have 2048 words": return Language.msg(l10n_entropy_error_wordlist_size);
            case "BIP39 wordlist unreadable": return Language.msg(l10n_entropy_error_unreadable);
            case "SHA-256 unavailable": return Language.msg(l10n_entropy_error_sha_unavailable);
            case "wordlist not loaded": return Language.msg(l10n_entropy_error_not_loaded);
            case "wordlist bounds wrong": return Language.msg(l10n_entropy_error_bounds);
            case "dice encoding length check failed": return Language.msg(l10n_entropy_error_encoding);
            case "raw truncation check failed": return Language.msg(l10n_entropy_error_truncation);
            case "dice-to-phrase vector failed": return Language.msg(l10n_entropy_error_dice_vector);
            case "last-word tool: candidate count failed": return Language.msg(l10n_entropy_error_candidate_count);
            case "last-word tool: known candidate missing": return Language.msg(l10n_entropy_error_candidate_missing);
            case "last-word tool: validator rejects known phrase": return Language.msg(l10n_entropy_error_rejects_known);
            case "last-word tool: validator accepts invalid phrase": return Language.msg(l10n_entropy_error_accepts_invalid);
            case "last-word tool: candidate fails checksum": return Language.msg(l10n_entropy_error_candidate_checksum);
            default: break;
        }
        for(int i=0;i<PATTERNS.length;i++) {
            java.util.regex.Matcher match=PATTERNS[i].matcher(value);
            if(!match.matches())continue;
            Object[] arguments=new Object[match.groupCount()];
            for(int j=0;j<arguments.length;j++) {
                String literal=match.group(j+1);
                arguments[j]=DIAGNOSTIC[i][j] ? message(literal,depth+1) : literal;
            }
            return Language.msg(RESOURCES[i],arguments);
        }
        return value;
    }
    private static final java.util.regex.Pattern[] PATTERNS={
        java.util.regex.Pattern.compile("init\\ failed:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("self\\-test\\ exception:\\ ((?s:.*))"),
        java.util.regex.Pattern.compile("wordlist\\ has\\ (-?[0-9]+)\\ words"),
        java.util.regex.Pattern.compile("BIP39\\ vector\\ (-?[0-9]+)\\ failed"),
        java.util.regex.Pattern.compile("check\\(\\)\\ rejects\\ valid\\ vector\\ (-?[0-9]+)"),
        java.util.regex.Pattern.compile("enter\\ 11,\\ 14,\\ 17,\\ 20\\ or\\ 23\\ words\\ \\(got\\ (-?[0-9]+)\\)"),
        java.util.regex.Pattern.compile("word\\ (-?[0-9]+)\\ \\(\"((?s:.*))\"\\)\\ is\\ not\\ in\\ the\\ BIP39\\ list")
    };
    private static final int[] RESOURCES={l10n_entropy_error_init,l10n_entropy_error_self_exception,l10n_entropy_error_word_count,l10n_entropy_error_vector,l10n_entropy_error_valid_vector,l10n_entropy_error_input_count,l10n_entropy_error_unknown_word};
    private static final boolean[][] DIAGNOSTIC={{true},{true},{false},{false},{false},{false},{false,false}};
}
